      'ob.f1Sub':"દરેક ખાનાની બાજુમાં માઇકનું બટન છે — બોલીને ભરો કે ટાઇપ કરો.",
      'ob.f1Say':"હવે તમારી માહિતી ભરો. દરેક ખાનાની બાજુમાં માઇકનું બટન છે.",
