      'tour.weather.t':"आज का मौसम और छिड़काव की चेतावनी",
      'tour.weather.d':"यह कार्ड आपके इलाके का मौसम दिखाता है। अगर अगले कुछ घंटों में बारिश हो सकती है, तो यहाँ चेतावनी आएगी कि अभी दवा मत छिड़किए, वरना दवा बह जाएगी और पैसा बर्बाद होगा।",
      'tour.weatherListen.t':"मौसम सुनने का बटन",
      'tour.weatherListen.d':"पढ़ना न आता हो तो कोई बात नहीं। इस बटन को दबाइए और पूरा मौसम तथा चेतावनी हिंदी में ज़ोर से सुनाई देगी।",
      'tour.photo.t':"पत्ती की फोटो यहाँ लगाइए",
      'tour.photo.d':"इस खाने पर टैप करके फोटो चुनें। एक ही पत्ती की साफ फोटो लें, अच्छी रोशनी में और सादे बैकग्राउंड पर। धुंधली फोटो से नतीजा सही नहीं आता।",
      'tour.camera.t':"कैमरा बटन",
      'tour.camera.d':"यह बटन सीधे आपके फ़ोन का कैमरा खोल देता है। खेत में खड़े होकर पत्ती की फोटो यहीं से खींच सकते हैं।",
      'tour.scan.t':"जाँच शुरू करने का बटन",
      'tour.scan.d':"फोटो चुनने के बाद यह बटन दबाइए। जाँच आपके फ़ोन के अंदर ही होती है, इसलिए इंटरनेट न हो तब भी काम करती है और आपकी फोटो कहीं नहीं जाती।",
      'tour.confidence.t':"भरोसे का प्रतिशत",
      'tour.confidence.d':"यहाँ हर रोग की संभावना प्रतिशत में दिखती है। अगर सबसे ऊपर वाला पचहत्तर प्रतिशत से कम है, तो ऐप कोई रोग नहीं बताता और साफ फोटो दोबारा माँगता है।",
      'tour.advisory.t':"रोग की पूरी सलाह",
      'tour.advisory.d':"रोग पहचानने के बाद यहाँ पूरी सलाह आती है — क्या करना है, कौन सी जैविक दवा, कौन सी रासायनिक दवा और कितनी मात्रा। छिड़काव से पहले अपने कृषि विज्ञान केंद्र से पुष्टि ज़रूर करें।",
