      'ui.a20':"ਵਿੱਘਾ",
      'ui.a21':"ਕਨਾਲ",
      'ui.a22':"ਚੁਣੀ ਫ਼ਸਲ ਦੇ ਪੱਤੇ ਦੀ ਸਾਫ਼ ਫ਼ੋਟੋ ਅਪਲੋਡ ਕਰੋ",
