      'ui.a33':"ਅਜਿਹੀਆਂ ਫ਼ੋਟੋਆਂ ਤੇ ਜਾਂਚ ਜਾਣ-ਬੁੱਝ ਕੇ ਰੋਕੀ ਗਈ ਹੈ, ਕਿਉਂਕਿ ਮਾਡਲ ਹਰ ਫ਼ੋਟੋ ਨੂੰ ਕਿਸੇ ਨਾ ਕਿਸੇ ਰੋਗ ਵਿੱਚ ਪਾ ਦਿੰਦਾ ਹੈ — ਤੇ ਗ਼ਲਤ ਸਲਾਹ ਨਾਲ ਫ਼ਸਲ ਦਾ ਨੁਕਸਾਨ ਹੋ ਸਕਦਾ ਹੈ।",
