      'ui.a35':"ਸਾਰੀਆਂ ਫ਼ੋਟੋਆਂ ਮਿਲਾ ਕੇ",
      'ui.a36':"ਠੀਕ ਤਰ੍ਹਾਂ ਪਛਾਣ ਨਹੀਂ ਹੋ ਸਕੀ",
      'ui.a37':"ਕਿਰਪਾ ਕਰਕੇ ਸਾਫ਼ ਫ਼ੋਟੋ ਲਵੋ, ਜਾਂ ਚੁਣੀ ਫ਼ਸਲ ਦੇ ਪੱਤੇ ਦੀ ਫ਼ੋਟੋ ਦਿਓ",
      'ui.a38':"ਪੱਤੇ ਨੂੰ ਤੇਜ਼ ਧੁੱਪ ਵਿੱਚ ਨਹੀਂ, ਛਾਂ ਦੀ ਸਾਫ਼ ਰੌਸ਼ਨੀ ਵਿੱਚ ਰੱਖੋ",
      'ui.a39':"ਕੈਮਰਾ 15–20 ਸੈਂਟੀਮੀਟਰ ਦੂਰ ਰੱਖੋ, ਪੱਤਾ ਪੂਰਾ ਫ੍ਰੇਮ ਵਿੱਚ ਹੋਵੇ",
      'ui.a40':"ਪਿੱਛੇ ਸਾਦਾ ਰੱਖੋ (ਹੱਥ ਜਾਂ ਕਾਗ਼ਜ਼ ਉੱਤੇ ਪੱਤਾ)",
