      'ui.a43':"ਸਾਰੀਆਂ ਸ਼੍ਰੇਣੀਆਂ ਦੀ ਸੰਭਾਵਨਾ",
      'ui.a44':"ਸਾਰੀਆਂ ਪਿਛਲੀਆਂ ਜਾਂਚਾਂ — ਸਿਰਫ਼ ਇਸੇ ਫ਼ੋਨ ਵਿੱਚ, ਕਿਤੇ ਅਪਲੋਡ ਨਹੀਂ ਹੁੰਦੀਆਂ",
