      'ui.a46':"ਕਿਸਾਨ ਸੱਥ",
      'ui.a47':"ਆਪਣੇ ਇਲਾਕੇ ਦੇ ਕਿਸਾਨਾਂ ਤੋਂ ਪੁੱਛੋ — ਜੋ ਜਵਾਬ ਮਾਡਲ ਨਹੀਂ ਦੇ ਸਕਦਾ",
      'ui.a48':"ਇੱਥੋਂ ਦੀ ਸਲਾਹ ਕਿਸਾਨਾਂ ਦੀ ਆਪਣੀ ਹੈ, ਖੇਤੀ ਵਿਭਾਗ ਦੀ ਨਹੀਂ। ਦਵਾਈ ਦੀ ਮਾਤਰਾ ਕ੍ਰਿਸ਼ੀ ਵਿਗਿਆਨ ਕੇਂਦਰ ਤੋਂ ਪੱਕੀ ਕਰੋ।",
      'ui.a49':"ਰੋਗ ਪੁਸਤਿਕਾ",
