      'ui.a51':"APK ਡਾਊਨਲੋਡ",
      'ui.a52':"ਇੰਸਟਾਲ ਕਰੋ",
      'ui.a53':"ਖੇਤੀ ਵਿਭਾਗ ਨੂੰ ਜਾਂਚ ਭੇਜੋ",
      'ui.a54':"ਤੁਹਾਡੇ ਇਲਾਕੇ ਵਿੱਚ ਰੋਗ ਫੈਲਣ ਤੇ ਵਿਭਾਗ ਸਮੇਂ ਸਿਰ ਚੇਤਾਵਨੀ ਭੇਜ ਸਕੇ, ਇਸ ਲਈ।",
      'ui.a55':"ਕੀ ਜਾਂਦਾ ਹੈ:",
      'ui.a56':"ਕੀ ਕਦੇ ਨਹੀਂ ਜਾਂਦਾ:",
      'ui.a57':"ਥਾਂ ਤਦੇ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਮੌਸਮ ਲਈ ਪਹਿਲਾਂ ਤੋਂ ਥਾਂ ਦਿੱਤੀ ਹੋਵੇ।",
      'ui.a58':"ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ — ਆਫ਼ਲਾਈਨ ਜਾਂਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨਿੱਜੀ ਰਹਿੰਦੀ ਹੈ।",
      'ui.a59':"ਭੇਜਣਾ ਚਾਲੂ ਕਰੋ",
      'ui.a60':"ਮੇਰਾ ਡਾਟਾ",
      'ui.a61':"ਇਹ ਐਪ ਤੁਹਾਡੇ ਫ਼ੋਨ ਤੇ ਕੀ ਰੱਖਦੀ ਹੈ — ਤੇ ਉਸਨੂੰ ਉਤਾਰਨ ਜਾਂ ਮਿਟਾਉਣ ਦਾ ਬਟਨ",
      'ui.a62':"ਪ੍ਰਾਈਵੇਸੀ ਨੀਤੀ",
      'ui.a63':"ਸ਼ਰਤਾਂ",
      'ui.a64':"ਆਫ਼ਲਾਈਨ ਮਾਡਲ",
      'ui.a65':"ਖੇਤ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਵਾਈ-ਫ਼ਾਈ ਤੇ ਮਾਡਲ ਡਾਊਨਲੋਡ ਕਰ ਲਵੋ — ਫਿਰ ਬਿਨਾਂ ਨੈੱਟਵਰਕ ਵੀ ਜਾਂਚ ਚੱਲੇਗੀ।",
      'ui.a66':"ਸਾਰੇ ਡਾਊਨਲੋਡ",
      'ui.a67':"ਆਫ਼ਲਾਈਨ ਆਵਾਜ਼",
      'ui.a68':"ਸਲਾਹ ਸੁਣਨ ਲਈ ਫ਼ੋਨ ਵਿੱਚ ਤੁਹਾਡੀ ਭਾਸ਼ਾ ਦੀ ਆਵਾਜ਼ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ — ਤਾਂ ਹੀ ਬਿਨਾਂ ਨੈੱਟਵਰਕ ਬੋਲੇਗੀ।",
