      'ui.a70':"ਇਹ ਐਪ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ",
      'ui.a71':"ਫ਼ੋਟੋ ਤੁਹਾਡੇ ਫ਼ੋਨ ਤੋਂ ਕਿਤੇ ਨਹੀਂ ਜਾਂਦੀ — ਮਾਡਲ ਫ਼ੋਨ ਵਿੱਚ ਹੀ ਚੱਲਦਾ ਹੈ (TensorFlow.js)।",
