      'ui.a73':"75% ਤੋਂ ਘੱਟ ਭਰੋਸਾ ਹੋਣ ਤੇ ਐਪ ਕੋਈ ਰੋਗ ਨਹੀਂ ਦੱਸਦੀ — ਦੁਬਾਰਾ ਫ਼ੋਟੋ ਮੰਗਦੀ ਹੈ।",
