      'ui.a75':"ਸਿਰਫ਼ ਮੌਸਮ",
      'ui.a76':"ਹਰ ਫ਼ਸਲ ਦਾ ਵੱਖਰਾ ਮਾਡਲ ਹੁੰਦਾ ਹੈ — ਇਸ ਲਈ ਸਟੀਕਤਾ ਬਿਹਤਰ ਰਹਿੰਦੀ ਹੈ।",
