      'ui.a80':"ਇਹ ਸਲਾਹ ਸੇਧ ਲਈ ਹੈ, ਆਖ਼ਰੀ ਫ਼ੈਸਲਾ ਨਹੀਂ।",
      'ui.a81':"ਕੋਈ ਵੀ ਛਿੜਕਾਅ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਕ੍ਰਿਸ਼ੀ ਵਿਗਿਆਨ ਕੇਂਦਰ / ਖੇਤੀ ਅਧਿਕਾਰੀ ਤੋਂ ਮਾਤਰਾ ਪੱਕੀ ਕਰੋ।",
      'ui.a82':"ਦਵਾਈ ਦੇ ਡੱਬੇ ਤੇ ਲਿਖੀਆਂ ਸਾਵਧਾਨੀਆਂ ਜ਼ਰੂਰ ਪੜ੍ਹੋ; ਛਿੜਕਾਅ ਵੇਲੇ ਮਾਸਕ ਤੇ ਦਸਤਾਨੇ ਪਾਓ।",
      'ui.a83':"ਵਾਢੀ ਤੋਂ ਪਹਿਲੇ ਦਿਨਾਂ ਵਿੱਚ (PHI) ਛਿੜਕਾਅ ਨਾ ਕਰੋ।",
