      'ob.introBody':'ਕ੍ਰਿਸ਼ੀ ਮਿੱਤਰ ਤੁਹਾਡੀ ਫ਼ਸਲ ਦੇ ਪੱਤੇ ਦੀ ਫ਼ੋਟੋ ਤੋਂ ਰੋਗ ਪਛਾਣਦਾ ਹੈ — ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ ਵੀ। ਇਹ ਦਵਾਈ ਤੇ ਸਹੀ ਮਾਤਰਾ ਦੱਸਦਾ ਹੈ, ਮੌਸਮ ਤੇ ਛਿੜਕਾਅ ਦੀ ਚੇਤਾਵਨੀ ਦਿੰਦਾ ਹੈ, ਨੇੜਲੀ ਮੰਡੀ ਦੇ ਭਾਅ ਵਿਖਾਉਂਦਾ ਹੈ, ਅਤੇ ਖੇਤੀ ਵਿਭਾਗ ਦੀਆਂ ਸੂਚਨਾਵਾਂ ਤੁਹਾਡੇ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। ਸਭ ਤੁਹਾਡੀ ਆਪਣੀ ਭਾਸ਼ਾ ਵਿੱਚ।',
