      'st.chandigarh':"சண்டிகர்",
      'ob.introTitle':'இந்த செயலி என்ன செய்கிறது',
      'ob.f1Title':"உங்கள் விவரங்களை நிரப்புங்கள்",
      'ob.f1Sub':"ஒவ்வொரு கட்டத்திற்கும் மைக் பொத்தான் உள்ளது — பேசியோ தட்டச்சு செய்தோ நிரப்பலாம்.",
      'ob.f1Say':"இப்போது உங்கள் விவரங்களை நிரப்புங்கள். ஒவ்வொரு கட்டத்திற்கும் மைக் பொத்தான் உள்ளது.",
      'ob.firstName':"முதல் பெயர்",
