      'ob.notAllowed':"கிடைக்கவில்லை — பின்னர் அமைப்பிலிருந்து",
      'ob.agree':"தனியுரிமைக் கொள்கையைப் படித்தேன், ஒப்புக்கொள்கிறேன்.",
      'ob.readPolicy':"கொள்கையைப் படிக்க",
      'ob.privacyGist':"உங்கள் படம் உங்கள் தொலைபேசியிலேயே பரிசோதிக்கப்படுகிறது. வேளாண்மைத் துறைக்கு பரிசோதனை நீங்களே அந்த வசதியை இயக்கினால் மட்டுமே அனுப்பப்படும்.",
      'ob.permSay':"இப்போது சில அனுமதிகள் தேவை. ஒவ்வொன்றின் காரணமும் கீழே எழுதப்பட்டுள்ளது.",
      'ob.f2Title':"உங்களிடம் எவ்வளவு நிலம் உள்ளது?",
      'ob.f2Sub':"இதனால் மருந்து மற்றும் உரத்தின் அளவு உங்கள் வயலுக்கு ஏற்ப சொல்லப்படும்.",
      'ob.f2Say':"உங்களிடம் எவ்வளவு நிலம் உள்ளது? எண்ணைச் சொல்லுங்கள் அல்லது எழுதுங்கள்.",
      'ob.landAmount':"நிலம்",
      'ob.unit':"அலகு",
      'ob.badLand':"நிலத்தின் அளவை எண்ணாக எழுதுங்கள், எ.கா. 2 அல்லது 1.5",
      'ob.finish':"முடிக்கவும்",
      'ob.unit.acre':"ஏக்கர்",
      'ob.unit.hectare':"ஹெக்டேர்",
      'ob.unit.bigha':"பிகா (தோராயமாக)",
      'ob.unit.guntha':"குந்தா",
      'ob.dlTitle':"இணையம் இல்லாமல் இயங்க",
      'ob.dlBody':"வயலில் அடிக்கடி நெட்வொர்க் இருக்காது. இப்போது இணையம் உள்ளது, எனவே அனைத்து பயிர்களின் பரிசோதனையையும் தொலைபேசியில் இறக்கிக் கொள்ளுங்கள் — பிறகு பரிசோதனை இணையம் இல்லாமல் இயங்கும்.",
      'ob.dlSay':"வயலில் அடிக்கடி நெட்வொர்க் இருக்காது. இப்போதே அனைத்து பயிர்களின் பரிசோதனையையும் இறக்கிக் கொள்ளுங்கள்.",
      'ob.dlNow':"இப்போதே இறக்கு",
      'ob.dlLater':"பிறகு",
      'ob.dlGoing':"இறங்குகிறது…",
      'ob.dlKeepOpen':"செயலியைத் திறந்தே வையுங்கள். இது ஒரு முறை செய்யும் வேலை.",
      'ob.dlDone':"முடிந்தது — இனி பரிசோதனை இணையம் இல்லாமலும் இயங்கும்.",
      'ob.dlFail':"முழுமையாக இறங்கவில்லை. பரவாயில்லை — பிறகு \"பழைய பரிசோதனைகள்\" பக்கத்திலிருந்து மீண்டும் முயற்சிக்கலாம்.",
      'ob.dlRetry':"மீண்டும் முயற்சி",
      'ob.dlOffline':"இப்போது இணையம் இல்லை. இணையம் வந்ததும் \"பழைய பரிசோதனைகள்\" பக்கத்திலிருந்து எப்போது வேண்டுமானாலும் இறக்கலாம்.",
      'ob.introBody':'கிருஷி மித்ரா உங்கள் பயிரின் இலைப் படத்திலிருந்து நோயைக் கண்டறிகிறது — இணையம் இல்லாமலும். மருந்தையும் சரியான அளவையும் சொல்கிறது, வானிலை மற்றும் தெளிப்பு குறித்து எச்சரிக்கிறது, அருகிலுள்ள சந்தை விலையைக் காட்டுகிறது, வேளாண்மைத் துறையின் அறிவிப்புகளை உங்களிடம் கொண்டு வருகிறது. அனைத்தும் உங்கள் மொழியில்.',
