      'ob.readPolicy':"ನೀತಿ ಓದಿ",
      'ob.privacyGist':"ನಿಮ್ಮ ಫೋಟೋ ನಿಮ್ಮ ಫೋನಿನಲ್ಲೇ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ. ಕೃಷಿ ಇಲಾಖೆಗೆ ಪರೀಕ್ಷೆ ನೀವು ಸ್ವತಃ ಆ ಸೌಲಭ್ಯ ಆನ್ ಮಾಡಿದರೆ ಮಾತ್ರ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
