      'ob.unit.bigha':"ಬಿಘಾ (ಸುಮಾರು)",
      'ob.unit.guntha':"ಗುಂಟಾ",
      'ob.dlTitle':"ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆ ಕೆಲಸ ಮಾಡಲು",
      'ob.dlBody':"ಹೊಲದಲ್ಲಿ ಆಗಾಗ ನೆಟ್‌ವರ್ಕ್ ಇರುವುದಿಲ್ಲ. ಈಗ ಇಂಟರ್ನೆಟ್ ಇದೆ, ಹಾಗಾಗಿ ಎಲ್ಲಾ ಬೆಳೆಗಳ ಪರೀಕ್ಷೆಯನ್ನು ಫೋನಿಗೆ ಇಳಿಸಿಕೊಳ್ಳಿ — ನಂತರ ಪರೀಕ್ಷೆ ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆ ನಡೆಯುತ್ತದೆ.",
