      'ob.dlOffline':"ಈಗ ಇಂಟರ್ನೆಟ್ ಇಲ್ಲ. ನೆಟ್ ಬಂದಾಗ \"ಹಳೆಯ ಪರೀಕ್ಷೆಗಳು\" ಪುಟದಿಂದ ಯಾವಾಗ ಬೇಕಾದರೂ ಇಳಿಸಬಹುದು.",
      'ob.introBody':'ಕೃಷಿ ಮಿತ್ರ ನಿಮ್ಮ ಬೆಳೆಯ ಎಲೆಯ ಫೋಟೋದಿಂದ ರೋಗವನ್ನು ಗುರುತಿಸುತ್ತದೆ — ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆಯೂ. ಔಷಧಿ ಮತ್ತು ಸರಿಯಾದ ಪ್ರಮಾಣ ಹೇಳುತ್ತದೆ, ಹವಾಮಾನ ಮತ್ತು ಸಿಂಪರಣೆ ಬಗ್ಗೆ ಎಚ್ಚರಿಸುತ್ತದೆ, ಹತ್ತಿರದ ಮಾರುಕಟ್ಟೆ ದರ ತೋರಿಸುತ್ತದೆ, ಕೃಷಿ ಇಲಾಖೆಯ ಸೂಚನೆಗಳನ್ನು ತಲುಪಿಸುತ್ತದೆ. ಎಲ್ಲವೂ ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ.',
