      'ui.a39':"ക്യാമറ 15–20 സെന്റിമീറ്റർ അകലെ വയ്ക്കുക, ഇല മുഴുവൻ ഫ്രെയിമിൽ വരണം",
      'ui.a40':"പശ്ചാത്തലം ലളിതമാക്കുക (കൈയിലോ കടലാസിലോ ഇല)",
      'ui.a41':"ഫോട്ടോ ഇളകിയതാകരുത്",
      'ui.a42':"നിങ്ങളുടെ വിളയ്ക്ക് നിർദേശിച്ച നടപടി",
      'ui.a43':"എല്ലാ വിഭാഗങ്ങളുടെയും സാധ്യത",
      'ui.a44':"എല്ലാ മുൻ പരിശോധനകളും — ഈ ഫോണിൽ മാത്രം, എവിടേക്കും അപ്‌ലോഡ് ചെയ്യില്ല",
      'ui.a45':"അവസാന പരിശോധനയുടെ അടിസ്ഥാനത്തിൽ ഉപദേശം",
      'ui.a46':"കർഷക ചാവടി",
      'ui.a47':"നിങ്ങളുടെ പ്രദേശത്തെ കർഷകരോട് ചോദിക്കുക — മോഡലിന് നൽകാനാവാത്ത ഉത്തരങ്ങൾ",
      'ui.a48':"ഇവിടത്തെ ഉപദേശം കർഷകരുടേതാണ്, കൃഷി വകുപ്പിന്റേതല്ല. മരുന്നിന്റെ അളവ് കൃഷി വിജ്ഞാന കേന്ദ്രത്തിൽ ഉറപ്പാക്കുക.",
      'ui.a49':"രോഗ പുസ്തിക",
      'ui.a50':"ഹോം സ്ക്രീനിൽ ഐക്കൺ വരും, ആപ്പ് ബ്രൗസർ ഇല്ലാതെ തുറക്കും, ഇന്റർനെറ്റ് ഇല്ലാതെയും പ്രവർത്തിക്കും.",
      'ui.a51':"APK ഡൗൺലോഡ്",
      'ui.a52':"ഇൻസ്റ്റാൾ ചെയ്യുക",
      'ui.a53':"കൃഷി വകുപ്പിലേക്ക് പരിശോധന അയയ്ക്കുക",
      'ui.a54':"നിങ്ങളുടെ പ്രദേശത്ത് രോഗം പടർന്നാൽ വകുപ്പിന് സമയത്ത് മുന്നറിയിപ്പ് നൽകാൻ.",
      'ui.a55':"എന്ത് അയയ്ക്കുന്നു:",
      'ui.a56':"എന്ത് ഒരിക്കലും അയയ്ക്കുന്നില്ല:",
      'ui.a57':"കാലാവസ്ഥയ്ക്കായി നിങ്ങൾ നേരത്തെ നൽകിയിട്ടുണ്ടെങ്കിൽ മാത്രമേ സ്ഥലം പോകൂ.",
      'ui.a58':"ഇന്റർനെറ്റ് ഇല്ലാതെ ഒന്നും അയയ്ക്കുന്നില്ല — ഓഫ്‌ലൈൻ പരിശോധന പൂർണമായും സ്വകാര്യമായിരിക്കും.",
      'ui.a59':"അയയ്ക്കൽ ഓണാക്കുക",
      'ui.a60':"എന്റെ ഡാറ്റ",
      'ui.a61':"ഈ ആപ്പ് നിങ്ങളുടെ ഫോണിൽ എന്ത് സൂക്ഷിക്കുന്നു — അത് ഇറക്കാനും മായ്ക്കാനുമുള്ള ബട്ടൺ",
      'ui.a62':"സ്വകാര്യതാ നയം",
      'ui.a63':"നിബന്ധനകൾ",
      'ui.a64':"ഓഫ്‌ലൈൻ മോഡലുകൾ",
      'ui.a65':"വയലിലേക്ക് പോകുന്നതിന് മുമ്പ് വൈ-ഫൈയിൽ മോഡലുകൾ ഡൗൺലോഡ് ചെയ്യുക — പിന്നെ നെറ്റ്‌വർക്ക് ഇല്ലാതെയും പരിശോധന നടക്കും.",
      'ui.a66':"എല്ലാം ഡൗൺലോഡ്",
      'ui.a67':"ഓഫ്‌ലൈൻ ശബ്ദം",
      'ui.a68':"ഉപദേശം കേൾക്കാൻ ഫോണിൽ നിങ്ങളുടെ ഭാഷയുടെ ശബ്ദം വേണം — എങ്കിലേ നെറ്റ്‌വർക്ക് ഇല്ലാതെ സംസാരിക്കൂ.",
      'ui.a69':"ശബ്ദം പരിശോധിക്കുക",
      'ui.a70':"ഈ ആപ്പ് എങ്ങനെ പ്രവർത്തിക്കുന്നു",
      'ui.a71':"ഫോട്ടോ നിങ്ങളുടെ ഫോണിൽ നിന്ന് എവിടേക്കും പോകുന്നില്ല — മോഡൽ ഫോണിൽ തന്നെ പ്രവർത്തിക്കുന്നു (TensorFlow.js).",
      'ui.a72':"ആദ്യമായി തുറന്ന ശേഷം ആപ്പ് ഇന്റർനെറ്റ് ഇല്ലാതെയും പ്രവർത്തിക്കും.",
      'ui.a73':"75%-ൽ താഴെ ഉറപ്പാണെങ്കിൽ ആപ്പ് ഒരു രോഗവും പറയില്ല — വീണ്ടും ഫോട്ടോ ചോദിക്കും.",
      'ui.a74':"ഉപദേശം കേൾക്കാനും കഴിയും — “കേൾക്കുക” ബട്ടൺ കൊണ്ട്.",
      'ui.a75':"കാലാവസ്ഥ മാത്രം",
      'ui.a76':"ഓരോ വിളയ്ക്കും വെവ്വേറെ മോഡൽ — അതുകൊണ്ട് കൃത്യത മെച്ചമാണ്.",
      'ui.a77':"ഓട്ടോ മോഡ്:",
      'ui.a78':"ഫോട്ടോ ഓൺലൈൻ പരിശോധനയുടെ സമയത്ത് മാത്രമേ അയയ്ക്കൂ — ഓഫ്‌ലൈൻ മോഡിൽ എവിടേക്കും പോകില്ല.",
      'ui.a79':"പ്രധാന ജാഗ്രത",
      'ui.a80':"ഈ ഉപദേശം വഴികാട്ടാനാണ്, അന്തിമ തീരുമാനമല്ല.",
      'ui.a81':"ഏത് തളിക്കലിനും മുമ്പ് നിങ്ങളുടെ കൃഷി വിജ്ഞാന കേന്ദ്രത്തിൽ / കൃഷി ഓഫീസറോട് അളവ് ഉറപ്പാക്കുക.",
      'ui.a82':"മരുന്നിന്റെ പാത്രത്തിൽ എഴുതിയ ജാഗ്രതകൾ നിർബന്ധമായും വായിക്കുക; തളിക്കുമ്പോൾ മാസ്കും കയ്യുറയും ധരിക്കുക.",
      'ui.a83':"വിളവെടുപ്പിന് തൊട്ടുമുമ്പുള്ള ദിവസങ്ങളിൽ (PHI) തളിക്കരുത്.",
      'photo.blurTitle':"ഫോട്ടോ മങ്ങിയതാണ്",
      'photo.blurBody':"ഫോട്ടോ ഇളകി, അതിനാൽ പുള്ളികൾ വ്യക്തമല്ല.",
      'photo.blurTip1':"ഇല ഒരു കൈകൊണ്ട് പിടിച്ച് ഇളകാതെ വയ്ക്കുക.",
      'photo.blurTip2':"ഫോൺ ഇലയിൽ നിന്ന് ഏകദേശം ഒരു ചാൺ അകലെ വയ്ക്കുക.",
