      'photo.darkTitle':"ഫോട്ടോ വളരെ ഇരുട്ടാണ്",
      'photo.darkBody':"ഇത്ര ഇരുട്ടിൽ ഇലയിലെ പുള്ളികൾ കാണാനേ കഴിയില്ല.",
      'photo.darkTip1':"പകൽ വെളിച്ചത്തിൽ എടുക്കുക — കടുത്ത വെയിലിലല്ല, തണലിൽ.",
      'photo.darkTip2':"സൂര്യൻ നിങ്ങളുടെ പിന്നിലായിരിക്കട്ടെ, വെളിച്ചം ഇലയിൽ വീഴട്ടെ.",
