      'ob.offline':"ഇന്റർനെറ്റ് ഇല്ല — അല്പം കഴിഞ്ഞ് ശ്രമിക്കുക.",
      'ob.permTitle':"കുറച്ച് അനുമതികൾ വേണം",
      'ob.permSub':"ഇവയില്ലാതെയും ആപ്പ് പ്രവർത്തിക്കും, പക്ഷേ ആ സൗകര്യങ്ങൾ നിൽക്കും. പിന്നീട് എപ്പോൾ വേണമെങ്കിലും ഓണാക്കാം.",
      'ob.permLoc':"സ്ഥലം (ലൊക്കേഷൻ)",
      'ob.permLocWhy':"നിങ്ങളുടെ പ്രദേശത്തെ കാലാവസ്ഥ, തളിക്കൽ മുന്നറിയിപ്പ്, അടുത്തുള്ള ചന്ത വില കാണിക്കാൻ.",
      'ob.permNotify':"അറിയിപ്പുകൾ",
      'ob.permNotifyWhy':"ആലിപ്പഴം, കീടം അല്ലെങ്കിൽ രോഗ മുന്നറിയിപ്പ് ആപ്പ് അടച്ചാലും നിങ്ങളിലെത്താൻ.",
      'ob.permCam':"ക്യാമറ",
      'ob.permCamWhy':"ഇലയുടെ ഫോട്ടോ എടുത്ത് രോഗം തിരിച്ചറിയാൻ. ഫോട്ടോ നിങ്ങളുടെ ഫോണിൽ തന്നെ പരിശോധിക്കുന്നു.",
      'ob.allow':"അനുമതി നൽകുക",
      'ob.allowed':"കിട്ടി",
      'ob.notAllowed':"കിട്ടിയില്ല — പിന്നീട് സെറ്റിംഗ്സിൽ നിന്ന്",
      'ob.agree':"സ്വകാര്യതാ നയം വായിച്ചു, സമ്മതിക്കുന്നു.",
      'ob.readPolicy':"നയം വായിക്കുക",
      'ob.privacyGist':"നിങ്ങളുടെ ഫോട്ടോ നിങ്ങളുടെ ഫോണിൽ തന്നെ പരിശോധിക്കുന്നു. കൃഷി വകുപ്പിലേക്ക് പരിശോധന നിങ്ങൾ സ്വയം ആ സൗകര്യം ഓണാക്കിയാൽ മാത്രമേ അയയ്ക്കൂ.",
      'ob.permSay':"ഇനി കുറച്ച് അനുമതികൾ വേണം. ഓരോന്നിന്റെയും കാരണം താഴെ എഴുതിയിട്ടുണ്ട്.",
      'ob.f2Title':"നിങ്ങൾക്ക് എത്ര ഭൂമിയുണ്ട്?",
      'ob.f2Sub':"ഇതുവഴി മരുന്നിന്റെയും വളത്തിന്റെയും അളവ് നിങ്ങളുടെ വയലിന് അനുസരിച്ച് പറയാം.",
      'ob.f2Say':"നിങ്ങൾക്ക് എത്ര ഭൂമിയുണ്ട്? സംഖ്യ പറയുക അല്ലെങ്കിൽ എഴുതുക.",
      'ob.landAmount':"ഭൂമി",
      'ob.unit':"അളവ്",
      'ob.badLand':"ഭൂമിയുടെ അളവ് സംഖ്യയായി എഴുതുക, ഉദാ. 2 അല്ലെങ്കിൽ 1.5",
