      'ob.unit.guntha':"ഗുണ്ഠ",
      'ob.dlTitle':"ഇന്റർനെറ്റ് ഇല്ലാതെ പ്രവർത്തിക്കാൻ",
      'ob.dlBody':"വയലിൽ പലപ്പോഴും നെറ്റ്‌വർക്ക് ഉണ്ടാകില്ല. ഇപ്പോൾ ഇന്റർനെറ്റ് ഉണ്ട്, അതുകൊണ്ട് എല്ലാ വിളകളുടെയും പരിശോധന ഫോണിലേക്ക് ഇറക്കിവയ്ക്കുക — പിന്നീട് പരിശോധന ഇന്റർനെറ്റ് ഇല്ലാതെ നടക്കും.",
      'ob.dlSay':"വയലിൽ പലപ്പോഴും നെറ്റ്‌വർക്ക് ഉണ്ടാകില്ല. ഇപ്പോൾ തന്നെ എല്ലാ വിളകളുടെയും പരിശോധന ഇറക്കിവയ്ക്കുക.",
