      'ob.dlKeepOpen':"ആപ്പ് തുറന്നിരിക്കട്ടെ. ഇത് ഒറ്റത്തവണ ചെയ്യേണ്ട ജോലിയാണ്.",
      'ob.dlDone':"കഴിഞ്ഞു — ഇനി പരിശോധന ഇന്റർനെറ്റ് ഇല്ലാതെയും നടക്കും.",
      'ob.dlFail':"പൂർണ്ണമായി ഇറങ്ങിയില്ല. കുഴപ്പമില്ല — പിന്നീട് \"പഴയ പരിശോധനകൾ\" പേജിൽ നിന്ന് വീണ്ടും ശ്രമിക്കാം.",
