      'ob.dlOffline':"ഇപ്പോൾ ഇന്റർനെറ്റ് ഇല്ല. നെറ്റ് വന്നാൽ \"പഴയ പരിശോധനകൾ\" പേജിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും ഇറക്കാം.",
      'ob.introBody':'കൃഷി മിത്ര നിങ്ങളുടെ വിളയുടെ ഇലയുടെ ഫോട്ടോയിൽ നിന്ന് രോഗം തിരിച്ചറിയുന്നു — ഇന്റർനെറ്റ് ഇല്ലാതെയും. മരുന്നും ശരിയായ അളവും പറയുന്നു, കാലാവസ്ഥയെയും തളിക്കലിനെയും കുറിച്ച് മുന്നറിയിപ്പ് നൽകുന്നു, അടുത്തുള്ള ചന്തയിലെ വില കാണിക്കുന്നു, കൃഷി വകുപ്പിന്റെ അറിയിപ്പുകൾ എത്തിക്കുന്നു. എല്ലാം നിങ്ങളുടെ ഭാഷയിൽ.',
