      'ui.a30':"ଯାଞ୍ଚ ଚାଲିଛି…",
      'ui.a31':"ଏହା ପତ୍ରର ଫଟୋ ଭଳି ଲାଗୁନାହିଁ",
      'ui.a32':"ଏହି ଫଟୋରେ ଗଛ ଭଳି କିଛି ମିଳିଲା ନାହିଁ।",
      'ui.a33':"ଏଭଳି ଫଟୋରେ ଯାଞ୍ଚ ଜାଣିଶୁଣି ବନ୍ଦ କରାଯାଇଛି, କାରଣ ମଡେଲ ପ୍ରତ୍ୟେକ ଫଟୋକୁ କୌଣସି ନା କୌଣସି ରୋଗରେ ପକାଇଦିଏ — ଆଉ ଭୁଲ ପରାମର୍ଶରେ ଫସଲର କ୍ଷତି ହୋଇପାରେ।",
      'ui.a34':"ତଥାପି ଯାଞ୍ଚ କରନ୍ତୁ",
      'ui.a35':"ସବୁ ଫଟୋ ମିଶାଇ",
      'ui.a36':"ଠିକ୍ ଭାବେ ଚିହ୍ନଟ ହୋଇପାରିଲା ନାହିଁ",
      'ui.a37':"ଦୟାକରି ସ୍ପଷ୍ଟ ଫଟୋ ନିଅନ୍ତୁ, କିମ୍ବା ବଛା ଫସଲର ପତ୍ରର ଫଟୋ ଦିଅନ୍ତୁ",
      'ui.a38':"ପତ୍ରକୁ ପ୍ରଖର ଖରାରେ ନୁହେଁ, ଛାଇର ସ୍ପଷ୍ଟ ଆଲୁଅରେ ରଖନ୍ତୁ",
      'ui.a39':"କ୍ୟାମେରାକୁ 15–20 ସେଣ୍ଟିମିଟର ଦୂରରେ ରଖନ୍ତୁ, ପତ୍ର ପୂରା ଫ୍ରେମରେ ରହୁ",
      'ui.a40':"ପଛପଟ ସାଧା ରଖନ୍ତୁ (ହାତ କିମ୍ବା କାଗଜ ଉପରେ ପତ୍ର)",
