      'ui.a44':"ସବୁ ପୂର୍ବ ଯାଞ୍ଚ — କେବଳ ଏହି ଫୋନରେ, କେଉଁଠି ଅପଲୋଡ୍ ହୁଏ ନାହିଁ",
