      'ui.a46':"ଚାଷୀ ଚଉପାଲ",
      'ui.a47':"ଆପଣଙ୍କ ଅଞ୍ଚଳର ଚାଷୀମାନଙ୍କୁ ପଚାରନ୍ତୁ — ଯାହା ଉତ୍ତର ମଡେଲ ଦେଇ ପାରିବ ନାହିଁ",
      'ui.a48':"ଏଠିକାର ପରାମର୍ଶ ଚାଷୀମାନଙ୍କ ନିଜର, କୃଷି ବିଭାଗର ନୁହେଁ। ଔଷଧର ମାତ୍ରା କୃଷି ବିଜ୍ଞାନ କେନ୍ଦ୍ରରୁ ନିଶ୍ଚିତ କରନ୍ତୁ।",
      'ui.a49':"ରୋଗ ପୁସ୍ତିକା",
      'ui.a50':"ହୋମ ସ୍କ୍ରିନରେ ଆଇକନ୍ ହୋଇଯିବ, ଆପ୍ ବ୍ରାଉଜର ବିନା ଖୋଲିବ ଓ ଇଣ୍ଟରନେଟ୍ ବିନା ଚାଲିବ।",
      'ui.a51':"APK ଡାଉନଲୋଡ୍",
      'ui.a52':"ଇନଷ୍ଟଲ୍ କରନ୍ତୁ",
