      'ui.a54':"ଆପଣଙ୍କ ଅଞ୍ଚଳରେ ରୋଗ ବ୍ୟାପିଲେ ବିଭାଗ ସମୟରେ ସତର୍କ କରିପାରିବ, ସେଥିପାଇଁ।",
      'ui.a55':"କଣ ପଠାଯାଏ:",
      'ui.a56':"କଣ କେବେ ପଠାଯାଏ ନାହିଁ:",
      'ui.a57':"ପାଗ ପାଇଁ ଆପଣ ଆଗରୁ ସ୍ଥାନ ଦେଇଥିଲେ ହିଁ ସ୍ଥାନ ଯାଏ।",
      'ui.a58':"ଇଣ୍ଟରନେଟ୍ ବିନା କିଛି ପଠାଯାଏ ନାହିଁ — ଅଫଲାଇନ ଯାଞ୍ଚ ସମ୍ପୂର୍ଣ୍ଣ ବ୍ୟକ୍ତିଗତ ରହେ।",
