      'ui.a60':"ମୋର ତଥ୍ୟ",
      'ui.a61':"ଏହି ଆପ୍ ଆପଣଙ୍କ ଫୋନରେ କଣ ରଖେ — ଓ ତାହା ଉତାରିବା କିମ୍ବା ଲିଭାଇବାର ବଟନ",
      'ui.a62':"ଗୋପନୀୟତା ନୀତି",
      'ui.a63':"ସର୍ତ୍ତାବଳୀ",
      'ui.a64':"ଅଫଲାଇନ ମଡେଲ",
      'ui.a65':"ଜମିକୁ ଯିବା ପୂର୍ବରୁ ୱାଇ-ଫାଇରେ ମଡେଲ ଡାଉନଲୋଡ୍ କରନ୍ତୁ — ତା ପରେ ନେଟୱାର୍କ ବିନା ମଧ୍ୟ ଯାଞ୍ଚ ଚାଲିବ।",
      'ui.a66':"ସବୁ ଡାଉନଲୋଡ୍",
      'ui.a67':"ଅଫଲାଇନ ସ୍ୱର",
