      'ui.a80':"ଏହି ପରାମର୍ଶ ମାର୍ଗଦର୍ଶନ ପାଇଁ, ଅନ୍ତିମ ନିଷ୍ପତ୍ତି ନୁହେଁ।",
      'ui.a81':"ଯେକୌଣସି ସ୍ପ୍ରେ ପୂର୍ବରୁ ଆପଣଙ୍କ କୃଷି ବିଜ୍ଞାନ କେନ୍ଦ୍ର / କୃଷି ଅଧିକାରୀଙ୍କଠାରୁ ମାତ୍ରା ନିଶ୍ଚିତ କରନ୍ତୁ।",
