      'ob.privacyGist':"ଆପଣଙ୍କ ଫଟୋ ଆପଣଙ୍କ ଫୋନରେ ହିଁ ଯାଞ୍ଚ ହୁଏ। କୃଷି ବିଭାଗକୁ ଯାଞ୍ଚ ସେତେବେଳେ ହିଁ ପଠାଯାଏ ଯେତେବେଳେ ଆପଣ ନିଜେ ସେହି ସୁବିଧା ଚାଲୁ କରନ୍ତି।",
      'ob.permSay':"ଏବେ କିଛି ଅନୁମତି ଦରକାର। ପ୍ରତ୍ୟେକର କାରଣ ତଳେ ଲେଖା ଅଛି।",
