      'ob.dlBody':"ଜମିରେ ପ୍ରାୟତଃ ନେଟୱାର୍କ ନଥାଏ। ଏବେ ନେଟ୍ ଅଛି, ତେଣୁ ସବୁ ଫସଲର ଯାଞ୍ଚ ଫୋନରେ ଉତାରି ନିଅନ୍ତୁ — ତା ପରେ ଯାଞ୍ଚ ଇଣ୍ଟରନେଟ୍ ବିନା ଚାଲିବ।",
