      'ob.introBody':'କୃଷି ମିତ୍ର ଆପଣଙ୍କ ଫସଲର ପତ୍ରର ଫଟୋରୁ ରୋଗ ଚିହ୍ନେ — ଇଣ୍ଟରନେଟ୍ ବିନା ମଧ୍ୟ। ଏହା ଔଷଧ ଓ ଠିକ୍ ମାତ୍ରା କହେ, ପାଗ ଓ ସ୍ପ୍ରେ ବିଷୟରେ ସତର୍କ କରେ, ପାଖ ବଜାରର ଦର ଦେଖାଏ, ଏବଂ କୃଷି ବିଭାଗର ସୂଚନା ଆପଣଙ୍କ ପାଖରେ ପହଞ୍ଚାଏ। ସବୁ ଆପଣଙ୍କ ନିଜ ଭାଷାରେ।',
