      'tour.crop.d':"यहाँ अपनी फसल पर टैप करें — जैसे धान, गेहूँ या गन्ना। जो फसल चुनेंगे, सिर्फ उसी का ए आई मॉडल फ़ोन में लोड होगा, इसलिए ऐप हल्का और तेज़ रहता है।",
      'tour.status.t':"ऊपर स्थिति दिखती है",
