      'tour.confidence.d':"यहाँ हर रोग की संभावना प्रतिशत में दिखती है। अगर सबसे ऊपर वाला पचहत्तर प्रतिशत से कम है, तो ऐप कोई रोग नहीं बताता और साफ फोटो दोबारा माँगता है।",
      'tour.advisory.t':"रोग की पूरी सलाह",
      'tour.advisory.d':"रोग पहचानने के बाद यहाँ पूरी सलाह आती है — क्या करना है, कौन सी जैविक दवा, कौन सी रासायनिक दवा और कितनी मात्रा। छिड़काव से पहले अपने कृषि विज्ञान केंद्र से पुष्टि ज़रूर करें।",
      'tour.advisoryListen.t':"सलाह सुनने का बटन",
      'tour.advisoryListen.d':"यह \"सुनें\" बटन पूरी सलाह हिंदी में ज़ोर से पढ़कर सुनाता है। खेत में काम करते हुए भी आप सुन सकते हैं।",
      'tour.voice.t':"बोलकर ऐप चलाइए",
      'tour.voice.d':"यह हरा माइक बटन दबाकर आप बोलकर ऐप चला सकते हैं। जैसे कहिए — \"कैमरा खोलो\", \"मौसम बताओ\", या \"सलाह पढ़ो\"। ऐप आपकी बात समझकर वही काम करेगा।",
      'tour.help.t':"यह मदद वाला बटन याद रखिए",
