      'ob.introBody':'کرشی مِتر آپ کی فصل کے پتے کی تصویر سے بیماری پہچانتا ہے — بغیر انٹرنیٹ کے بھی۔ یہ دوا اور صحیح مقدار بتاتا ہے، موسم اور چھڑکاؤ کی وارننگ دیتا ہے، قریبی منڈی کے بھاؤ دکھاتا ہے، اور محکمہ زراعت کی اطلاعات آپ تک پہنچاتا ہے۔ سب کچھ آپ کی اپنی زبان میں۔',
